success.assertion:
for(const mode of['miss','blocked','control']){const s=make({move:10780,index:-1,soul:true,hit:mode!=='miss'});if(mode==='miss')timer(s,0,'攻击必失');if(mode==='blocked')timer(s,0,'skillBlock');if(mode==='control')s.fighters[0].ailments['害怕']=2;turn(s);assert.equal(s.fighters[0].soulState.phalanx2044?.hits??0,0);assert.equal(sum(s,'percent'),0);}
const a=make({move:10780,index:-1,soul:true,aStats:{def:300,spd:500}});turn(a,24585);assert.equal(a.fighters[0].soulState.phalanx2044?.hits??0,0);turn(a);assert.equal(sum(a,'percent'),150);
const b=make({move:10780,index:-1,soul:true,aStats:{def:300,spd:500}});timer(b,1,'攻击伤害免疫');timer(b,1,'固定百分比免疫');turn(b);assert.equal(sum(b),0);assert.equal(sum(b,'percent'),0);assert.equal(b.fighters[0].soulState.phalanx2044.hits,1);delete b.fighters[1].effects['固定百分比免疫'];turn(b);assert.equal(sum(b),0);assert.equal(sum(b,'percent'),250);

